CREATE DATABASE IF NOT EXISTS rebox CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rebox;
SET NAMES utf8mb4;
CREATE TABLE roles(id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(24) NOT NULL UNIQUE,name VARCHAR(60) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_id TINYINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(24) UNIQUE,password_hash VARCHAR(255) NOT NULL,avatar VARCHAR(500),status ENUM('ACTIVE','LOCKED') NOT NULL DEFAULT 'ACTIVE',points INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id),INDEX(role_id,status)) ENGINE=InnoDB;
CREATE TABLE user_addresses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(60),recipient VARCHAR(120),phone VARCHAR(24),address_line VARCHAR(255) NOT NULL,is_default TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT,status TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT,material VARCHAR(100),capacity_ml INT UNSIGNED NOT NULL,dimensions VARCHAR(100),weight_g INT UNSIGNED,food_types VARCHAR(255),image_url VARCHAR(500),rental_price DECIMAL(12,2) NOT NULL,deposit_amount DECIMAL(12,2) NOT NULL,late_fee_per_day DECIMAL(12,2) NOT NULL DEFAULT 0,max_rental_days SMALLINT UNSIGNED NOT NULL DEFAULT 7,status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id),INDEX(category_id,status)) ENGINE=InnoDB;
CREATE TABLE locations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(140) NOT NULL,address VARCHAR(255) NOT NULL,phone VARCHAR(24),opening_hours VARCHAR(180),accepts_returns TINYINT(1) DEFAULT 1,capacity INT UNSIGNED DEFAULT 0,status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE staff_locations(user_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,location_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE containers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED,serial_code VARCHAR(60) NOT NULL UNIQUE,qr_token CHAR(64) NOT NULL UNIQUE,lifecycle_status ENUM('AVAILABLE','RESERVED','RENTED','RETURNED_DIRTY','CLEANING','MAINTENANCE','LOST','RETIRED') NOT NULL DEFAULT 'AVAILABLE',usage_count INT UNSIGNED DEFAULT 0,last_inspected_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(location_id) REFERENCES locations(id),INDEX(location_id,lifecycle_status,product_id)) ENGINE=InnoDB;
CREATE TABLE rental_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_code VARCHAR(24) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,pickup_location_id BIGINT UNSIGNED NOT NULL,planned_return_location_id BIGINT UNSIGNED NOT NULL,order_status ENUM('PENDING_PAYMENT','CONFIRMED','READY_FOR_PICKUP','RENTED','PARTIALLY_RETURNED','RETURNED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING_PAYMENT',rental_start_at DATETIME NOT NULL,due_at DATETIME NOT NULL,returned_at DATETIME,rental_subtotal DECIMAL(12,2) NOT NULL,deposit_total DECIMAL(12,2) NOT NULL,discount_total DECIMAL(12,2) NOT NULL DEFAULT 0,fee_total DECIMAL(12,2) NOT NULL DEFAULT 0,grand_total DECIMAL(12,2) NOT NULL,note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(pickup_location_id) REFERENCES locations(id),FOREIGN KEY(planned_return_location_id) REFERENCES locations(id),INDEX(user_id,order_status),INDEX(due_at,order_status)) ENGINE=InnoDB;
CREATE TABLE rental_order_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,actor_user_id BIGINT UNSIGNED NULL,event_type ENUM('ORDER_CREATED','PAYMENT_CONFIRMED','HANDOVER','RETURN_RECEIVED','CLEANED','DEPOSIT_REFUNDED','ORDER_CANCELLED') NOT NULL,location_id BIGINT UNSIGNED NULL,container_id BIGINT UNSIGNED NULL,condition_status VARCHAR(24),note VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES rental_orders(id) ON DELETE CASCADE,FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(container_id) REFERENCES containers(id) ON DELETE SET NULL,INDEX(order_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE rental_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,unit_rental_price DECIMAL(12,2) NOT NULL,unit_deposit DECIMAL(12,2) NOT NULL,rental_days SMALLINT UNSIGNED NOT NULL,line_total DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES rental_orders(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE rental_item_containers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rental_item_id BIGINT UNSIGNED NOT NULL,container_id BIGINT UNSIGNED NOT NULL,checkout_at DATETIME,checkin_at DATETIME,checkout_condition VARCHAR(80),return_condition VARCHAR(80),item_status ENUM('RESERVED','OUT','RETURNED','MISSING','DAMAGED') DEFAULT 'RESERVED',UNIQUE KEY(rental_item_id,container_id),FOREIGN KEY(rental_item_id) REFERENCES rental_items(id),FOREIGN KEY(container_id) REFERENCES containers(id)) ENGINE=InnoDB;
CREATE TABLE rental_extensions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,requested_due_at DATETIME NOT NULL,approved_due_at DATETIME,extra_fee DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,processed_by BIGINT UNSIGNED,FOREIGN KEY(order_id) REFERENCES rental_orders(id),FOREIGN KEY(processed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE returns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,return_code VARCHAR(24) NOT NULL UNIQUE,returned_at DATETIME NOT NULL,notes TEXT,FOREIGN KEY(order_id) REFERENCES rental_orders(id),FOREIGN KEY(location_id) REFERENCES locations(id),FOREIGN KEY(staff_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE return_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,return_id BIGINT UNSIGNED NOT NULL,container_id BIGINT UNSIGNED NOT NULL,condition_status ENUM('CLEAN','DIRTY','DAMAGED','MISSING') NOT NULL,damage_fee DECIMAL(12,2) DEFAULT 0,note VARCHAR(500),FOREIGN KEY(return_id) REFERENCES returns(id),FOREIGN KEY(container_id) REFERENCES containers(id)) ENGINE=InnoDB;
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,payment_type ENUM('RENTAL','LATE_FEE','EXTENSION','REFUND') NOT NULL,provider ENUM('CASH','BANK_TRANSFER','DEMO','GATEWAY') NOT NULL DEFAULT 'DEMO',provider_transaction_id VARCHAR(190) UNIQUE,amount DECIMAL(12,2) NOT NULL,status ENUM('PENDING','PAID','FAILED','REFUNDED','PARTIAL_REFUND') DEFAULT 'PENDING',paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES rental_orders(id),INDEX(order_id,status)) ENGINE=InnoDB;
CREATE TABLE deposit_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,transaction_type ENUM('HOLD','REFUND','DEDUCTION','ADJUSTMENT') NOT NULL,amount DECIMAL(12,2) NOT NULL,status ENUM('PENDING','COMPLETED','FAILED') DEFAULT 'PENDING',reference_payment_id BIGINT UNSIGNED,reason VARCHAR(500),processed_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES rental_orders(id),FOREIGN KEY(reference_payment_id) REFERENCES payments(id),FOREIGN KEY(processed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE promotions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,description VARCHAR(255),discount_type ENUM('PERCENT','FIXED') NOT NULL,discount_value DECIMAL(12,2) NOT NULL,min_order_value DECIMAL(12,2) DEFAULT 0,starts_at DATETIME,ends_at DATETIME,usage_limit INT UNSIGNED,per_user_limit INT UNSIGNED DEFAULT 1,status TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE promotion_usages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,promotion_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,discount_amount DECIMAL(12,2) NOT NULL,used_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(order_id),FOREIGN KEY(promotion_id) REFERENCES promotions(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES rental_orders(id)) ENGINE=InnoDB;
CREATE TABLE maintenance_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,container_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,maintenance_type ENUM('CLEANING','INSPECTION','REPAIR') NOT NULL,result_status ENUM('IN_PROGRESS','PASSED','FAILED') DEFAULT 'IN_PROGRESS',description TEXT,cost DECIMAL(12,2) DEFAULT 0,started_at DATETIME NOT NULL,completed_at DATETIME,FOREIGN KEY(container_id) REFERENCES containers(id),FOREIGN KEY(staff_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment TEXT,status ENUM('PENDING','PUBLISHED','HIDDEN') DEFAULT 'PUBLISHED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(rating BETWEEN 1 AND 5),UNIQUE KEY(user_id,product_id,order_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(order_id) REFERENCES rental_orders(id)) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,channel ENUM('IN_APP','EMAIL','SMS') DEFAULT 'IN_APP',read_at DATETIME,sent_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,read_at)) ENGINE=InnoDB;
CREATE TABLE points_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED,points_change INT NOT NULL,reason VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES rental_orders(id)) ENGINE=InnoDB;
CREATE TABLE inventory_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,container_id BIGINT UNSIGNED NOT NULL,from_location_id BIGINT UNSIGNED,to_location_id BIGINT UNSIGNED,actor_user_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(container_id) REFERENCES containers(id),FOREIGN KEY(from_location_id) REFERENCES locations(id),FOREIGN KEY(to_location_id) REFERENCES locations(id),FOREIGN KEY(actor_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT UNSIGNED,before_data JSON,after_data JSON,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id),INDEX(entity_type,entity_id),INDEX(actor_user_id,created_at)) ENGINE=InnoDB;
